def _frozen(x):assert is_dataclass(x) and type(x).__dataclass_params__.frozen and "__dict__" not in type(x).__slots__
def test_public_contract_is_immutable_and_zero_authority():
 assert tuple(f.name for f in fields(LiveProviderActivationPolicyV1))==_P and tuple(f.name for f in fields(LiveProviderActivationEvidenceV1))==_E and tuple(f.name for f in fields(LiveProviderActivationDecisionV1))==_D and tuple(f.name for f in fields(LiveProviderActivationAuditEvidenceV1))==_A and tuple(f.name for f in fields(LiveProviderActivationFailureV1))==_F
 decision=evaluate_live_provider_activation_readiness_v1(_p(),_e());audit=build_live_provider_activation_audit_evidence_v1(_p(),_e(),decision)
 for x in (_p(),_e(),decision,audit):_frozen(x)
 with pytest.raises(FrozenInstanceError):_p().network_connection_authorized=True # type: ignore[misc]
def test_missing_governance_fails_closed_without_any_activation():
 d=evaluate_live_provider_activation_readiness_v1(_p(),_e(owner_authorized=False,repository_clean=False,credential_source_configured=False,reconciliation_ready=False))
 assert {"OWNER_AUTHORIZATION_REQUIRED","REPOSITORY_NOT_CLEAN","CREDENTIAL_SOURCE_NOT_CONFIGURED","RECONCILIATION_NOT_READY"}.issubset(d.failure_codes) and tuple(d.failure_codes)==tuple(sorted(d.failure_codes)) and set(d.failure_codes).issubset(_C) and not d.ready
 assert (d.credential_loading_authorized,d.network_connection_authorized,d.provider_transmission_authorized,d.production_runtime_authorized,d.publication_authorized,d.trading_authorized)==(False,)*6
def test_structural_readiness_is_only_eligible_for_separate_authorization():
 d=evaluate_live_provider_activation_readiness_v1(_p(),_e())
 assert d.ready and not any((d.credential_loading_authorized,d.network_connection_authorized,d.provider_transmission_authorized,d.production_runtime_authorized,d.publication_authorized,d.trading_authorized))
