 p,e=_p(),_e();d=evaluate_live_provider_activation_readiness_v1(p,e);assert build_live_provider_activation_audit_evidence_v1(p,e,d)==build_live_provider_activation_audit_evidence_v1(p,e,d)
 with pytest.raises(ValueError):build_live_provider_activation_audit_evidence_v1(p,_e(provider_id="other-provider-v1"),d)
